async function optimizeVercelConfig() {
  logSection('OPTIMIZING VERCEL CONFIGURATION');
  
  const vercelJsonPath = path.join(process.cwd(), 'vercel.json');
  
  try {
    // Read current config
    const currentConfig = JSON.parse(fs.readFileSync(vercelJsonPath, 'utf8'));
    
    // Create optimized config
    const optimizedConfig = {
      ...currentConfig,
      // Add build command optimization
      buildCommand: 'vercel build',
      
      // Add Content Security Policy
      headers: [
        ...currentConfig.headers,
        {
          source: '/(.*)',
          headers: [
            {
              key: 'Content-Security-Policy',
              value: "default-src 'self'; script-src 'self' 'unsafe-inline' 'unsafe-eval' https://www.googletagmanager.com https://connect.facebook.net https://em.realscout.com; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src 'self' https://fonts.gstatic.com; img-src 'self' data: https: blob:; connect-src 'self' https://api.realscout.com https://www.googletagmanager.com; frame-src 'self' https://www.google.com;"
            }
          ]
        }
      ],
      
      // Add environment variables
      env: {
        ...currentConfig.env,
        NEXT_PUBLIC_SITE_URL: 'https://www.summerlinwestrealestate.com',
        NODE_ENV: 'production'
      },
      
      // Add build environment optimization
      build: {
        ...currentConfig.build,
        env: {
          ...currentConfig.build?.env,
          NEXT_TELEMETRY_DISABLED: '1',
          NODE_OPTIONS: '--max-old-space-size=4096'
        }
      },
      
      // Add functions configuration for better performance
      functions: {
        'app/api/**/*.ts': {
          maxDuration: 30
        }
      },
      
      // Add edge configuration
      edge: true
    };
    
    // Write optimized config
    fs.writeFileSync(vercelJsonPath, JSON.stringify(optimizedConfig, null, 2));
    
    logSuccess('vercel.json optimized');
    optimizations.vercelConfig.push('Added build command optimization');
    optimizations.vercelConfig.push('Added Content Security Policy');
    optimizations.vercelConfig.push('Added environment variables');
    optimizations.vercelConfig.push('Added build environment optimization');
    optimizations.vercelConfig.push('Added functions configuration');
    optimizations.vercelConfig.push('Enabled edge functions');
    
  } catch (error) {
    logWarning(`Could not optimize vercel.json: ${error.message}`);
  }
}

